import math
from collections import defaultdict

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t_i = int(parts[0])
        x_prime = int(parts[1])
        y_i = int(parts[2])
        x_i = x_prime / 100000.0
        operations.append((t_i, x_i, y_i))

    # earliest_time[j] = earliest time step to reach exactly j bananas
    earliest_time = [-1] * (m + 1)
    earliest_time[0] = 0

    # current_reachable[j] = True if j bananas is reachable
    current_reachable = {0}

    for step in range(1, n + 1):
        t_i, x_i, y_i = operations[step - 1]
        next_reachable = set(current_reachable)

        # For each currently reachable state, try all possible application counts
        for k in current_reachable:
            if k > m:
                continue

            # For type 1: k := ceil(k + x_i) applied a_i times
            if t_i == 1:
                if x_i > 0:
                    increment = math.ceil(x_i) - math.floor(x_i) + 1  # ceil(k + x_i) - k

                    # We can apply the operation 0 to y_i times
                    # Each application: new_k = ceil(old_k + x_i)
                    temp = k
                    for a in range(y_i + 1):
                        if temp > m:
                            break
                        if temp not in next_reachable:
                            next_reachable.add(temp)

                        temp = math.ceil(temp + x_i)
            # For type 2: k := ceil(k * x_i) applied a_i times
            elif t_i == 2:
                if x_i > 1:
                    temp = k
                    for a in range(y_i + 1):
                        if temp > m:
                            break
                        if temp not in next_reachable:
                            next_reachable.add(temp)

                        temp = math.ceil(temp * x_i)

        # Update current reachable states
        current_reachable = next_reachable

        # Record earliest time for each reachable state
        for j in range(1, m + 1):
            if j in current_reachable:
                earliest_time[j] = step

    # Format output
    result = []
    for j in range(1, m + 1):
        result.append(str(earliest_time[j]))

    return '\n' + ' '.join(result) + '\n'

