def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse costs - A[i][j] = cost for city i to build rail to city j
    # Cities are 0-indexed internally, 1-indexed in output
    costs = []
    for i in range(n):
        row = []
        line = lines[i + 1].split()
        # Skip A[i,i] (diagonal), but line contains N-1 values in order
        for j in range(n):
            if j != i:
                row.append(int(line[j]))
        costs.append(row)

    # Build preference lists based on each city's cost
    # prefs[i][j] = rank of city j for city i (lower rank = better)
    prefs = []
    for i in range(n):
        adj = []
        for j in range(n):
            if i != j:
                adj.append((costs[i][j], j))  # (cost, city)
        # Sort by cost (lower is better), stable sort for ties
        adj.sort(key=lambda x: x[0])
        prefs.append(adj)

    # Try to find a stable matching
    # Start with an initial assignment
    # partnership[i] = city i is paired with
    # unpaired[i] = True if city i has no partner

    def get_partner(i):
        if i >= 0 and partnership[i] is not None:
            return partnership[i]
        return None

    def partner_chooses(i, other):
        """Check if city i prefers other over current partner"""
        p = get_partner(i)
        if p is None:
            return True
        rank_o = prefs[i].index((costs[i][other], other))
        rank_p = prefs[i].index((costs[i][p], p))
        return rank_o < rank_p

    def is_blocking_pair(i, j):
        """Check if (i,j) forms a blocking pair"""
        if get_partner(i) is not None and get_partner(j) is not None:
            p_i = get_partner(i)
            p_j = get_partner(j)
            if i == p_j and j == p_i:
                return False  # Already paired with each other
            return partner_chooses(i, j) and partner_chooses(j, i)
        return False

    partnership = [None] * n
    pending_pairs = []  # (i, j) pairs waiting

    # Maximum iterations to prevent infinite loops
    max_iter = n * n * 100

    for _ in range(max_iter):
        has_blocking = False
        for i in range(n):
            for j in range(i + 1, n):
                if is_blocking_pair(i, j):
                    has_blocking = True
                    # Unpair i and j with current partners
                    p_i = get_partner(i)
                    p_j = get_partner(j)
                    if p_i is not None and p_i != j:
                        partnership[p_i] = None
                        partnership[i] = p_i  # i is now unpaired
                    if p_j is not None and p_j != i:
                        partnership[p_j] = None
                        partnership[j] = p_j  # j is now unpaired

                    # Now pair i and j
                    partnership[i] = j
                    partnership[j] = i
                    break
            if has_blocking:
                break
        if not has_blocking:
            break
        if partnership.count(None) == 0:
            break

    # Check for stability
    stable = True
    for i in range(n):
        for j in range(i + 1, n):
            if is_blocking_pair(i, j):
                stable = False
                break
        if not stable:
            break

    if not stable:
        return "-1\n"

    # Check if all cities are paired
    for i in range(n):
        if partnership[i] is None:
            return "-1\n"

    # Convert to 1-indexed output
    result = []
    for i in range(n):
        result.append(str(partnership[i] + 1) + "\n")

    return "".join(result)

