from collections import deque
import itertools

def bfs_distances(adj, N, start):
    dist = (-1) * (N + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

def solve(N, edges):
    if N == 1:
        return "0\n1"

    # Build adjacency list (1-indexed)
    adj = [[] for _ in range(N + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # All pairs shortest paths using BFS from each node
    all_dist = [bfs_distances(adj, N, i) for i in range(1, N + 1)]

    dist_matrix = [[all_dist[i][j - 1] for j in range(1, N + 1)] for i in range(1, N + 1)]

    # For small N, brute force
    if N <= 10:
        max_total = 0
        best_perm = None

        for perm in itertools.permutations(range(1, N + 1)):
            # Check derangement
            valid = all(perm[i] != i + 1 for i in range(N))
            if valid:
                total = sum(dist_matrix[i + 1][perm[i] - 1] for i in range(N))
                if total > max_total:
                    max_total = total
                    best_perm = perm

        return f"{max_total}\n{' '.join(map(str, best_perm))}"

    # For larger N, use greedy with multiple starts
