def solution(input_str):
    parts = input_str.strip().split('\n')
    n = int(parts[0])
    arr = list(map(int, parts[1].split()))

    # Function to check if a sequence is a geometric progression
    def is_geometric(seq):
        if len(seq) <= 2:
            return True

        # All zeros is a valid GP
        if all(x == 0 for x in seq):
            return True

        # Find the first non-zero element
        first_nonzero_idx = -1
        for i in range(len(seq)):
            if seq[i] != 0:
                first_nonzero_idx = i
                break

        # If no non-zero element, already all zeros
        if first_nonzero_idx == -1:
            return True

        # Calculate the common ratio from first two non-zero consecutive elements
        ratio_computed = seq[first_nonzero_idx + 1] / seq[first_nonzero_idx]

        # Check all consecutive pairs after that
        for i in range(first_nonzero_idx, len(seq) - 1):
            if seq[i] == 0 or seq[i + 1] == 0:
                # After first non-zero, can't have zeros
                return False
            actual_ratio = seq[i + 1] / seq[i]
            if abs(actual_ratio - ratio_computed) > 1e-9:
                return False

        return True

    # Check if the original sequence is already a GP
    if is_geometric(arr):
        return "0\n"

    # Try removing each element and check if the result is a GP
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_geometric(new_arr):
            return "1\n"

    # If neither is possible
    return "2\n"


