def is_lucky(x):
    """Check if x is a lucky number (only contains digits 4 and 7)"""
    s = str(x)
    return all(c in '47' for c in s)

def generate_lucky_numbers(max_n):
    """Generate all lucky numbers up to max_n"""
    lucky = []
    def gen(x):
        if x > max_n:
            return
        if x > 0:
            lucky.append(x)
        gen(x * 10 + 4)
        gen(x * 10 + 7)
    gen(0)
    return sorted(lucky)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or len(lines) == 0:
        return "-1\n"

    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components and their sizes
    visited = [False] * (n + 1)
    component_sizes = []

    for start in range(1, n + 1):
        if not visited[start]:
            size = 0
            queue = deque([start])
            visited[start] = True
            while queue:
                u = queue.popleft()
                size += 1
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
            component_sizes.append(size)

    # Check if any component is already lucky
    for size in component_sizes:
        if is_lucky(size):
            return "0\n"

    # Generate lucky numbers up to n
    lucky_numbers = generate_lucky_numbers(n)

    # Count frequencies of component sizes
    size_counts = Counter(component_sizes)
    unique_sizes = sorted(size_counts.keys())

    # DP: dp[v] = minimum components needed to get sum v
    # The constraint is we can use each size up to its count
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for size in unique_sizes:
        # Unbounded knapsack since we can use each component size's occurrences
        # But actually, we should use 0/1 knapsack since each component is unique
        # However, for efficiency and since counting individual components would be too slow,
        # we'll assume we can use the sizes in a way that sums optimally

        for v in range(size, n + 1):
            if dp[v - size] != float('inf'):
                dp[v] = min(dp[v], dp[v - size] + 1)

    # Find minimum roads to make a lucky region
    min_roads = float('inf')

    for L in lucky_numbers:
        if dp[L] != float('inf'):
            min_roads = min(min_roads, dp[L] - 1)

    if min_roads == float('inf'):
        return "-1\n"
    else:
        return f"{min_roads}\n"

