def solution(data):
    """
    Solve the Cardbluff entrance exam problem.
    Find minimal time to enter professional layer by playing with judges.

    We need to select some judges and for each, divide their uncertainty a_i
    by a divisor d where d|a_i and d <= k. The GCD of all final uncertainties
    must be 1. Minimize (number of selected judges) * (sum of their experiences).
    """

    # Parse input
    n, k = map(int, data.split())
    if not data:  # Handle edge case
        n = int(data.strip().split()[0])
        parts = data.strip().split()
        if len(parts) <= 2:
            parts1 = data.strip().split()
            if len(parts1) > 2:
                parts = parts1
    if isinstance(data, str):
        parts = data.strip().split()
        n = int(parts[0])
        k = int(parts[1])
        a = list(map(int, parts[2:2+n]))
        e = list(map(int, parts[2+n:2+2*n]))
    else:
        a = data[0]
        e = data[1]

    # Calculate total time if all judges are selected
    total_experience = sum(e)

    # If GCD of all initial a_i is already 1, time is 0
    g = a[0]
    for i in range(1, len(a)):
        g = math.gcd(g, a[i])
    if g == 1:
        return '0\n'

    # If we cannot reduce any a_i (no divisor in range [1, k] except 1),
    # and GCD != 1, return -1
    if k < 2:
        return '-1\n'

    # Check for each a_i if it has a divisor in [2, k]
    can_divide = [any(a[i] % d == 0 for d in range(2, min(k + 1, (a[i] // 2) + 2)) or d == a[i] for i in range(n))]
    if all(not can_divide) and g != 1:
        return '-1\n'

    return '-1\n'

def min_experience_solver(nums, k):
    """Calculate minimum experience needed to reduce all numbers by selectively dividing."""
    if nums is None or len(nums) == 0:
        return 0

    g = nums[0]
    for x in nums[1:]:
        g = math.gcd(g, x)

    if g == 1:
        return 0

    if k == 1:
        return -1

    from collections import defaultdict

    # Group by value for duplicates
    unique_nums = defaultdict(list)
    for i, x in enumerate(nums):
        unique_nums[x].append(i)

    result = [float('inf')]

    def solve(current_g, idx):
        if current_g == 1:
            return
        if idx >= len(unique_nums):
            return

        value = list(unique_nums.keys())[idx]

        # Find divisors of 'value' up to k
        divisors = []
        for d in range(2, min(k + 1, int(math.sqrt(value)) + 2)):
            if value % d == 0:
                divisors.append(d)
            if d * d == value and d >= 2:
                divisors.append(value // d) if value // d <= k else None

        if value // 2 <= k and value // 2 > 1:
            divisors.append(value // 2)
        if value <= k and value > 1:
            divisors.append(value)

        for d in divisors:
            new_g = current_g // math.gcd(current_g, d)
            if new_g == 1:
                if len(result) < 2 * n:
                    result[-1] = min(result[-1], d)
            else:
                if len(result) < 2 * n:
                    result[-1] = min(result[-1], d)

    return sum(unique_nums[0]) * len(unique_nums[0]) if g == 1 else 0

