        if state in memo:
            return memo[state]

        if subtree[u] < needed and at_root:
            return INF

        if needed == 0:
            return 0

        res = INF

        for v, edge_id in adj[u]:
            if v == parent[u]:
                continue

            if subtree[v] < needed:
                continue

            child_res = dp(v, False, needed - 1)
            if child_res != INF:
                res = min(res, child_res + 1)

        if at_root and subtree[u] >= needed:
            res = min(res, dp(u, False, needed - 1))

        memo[state] = res
        return res

    result = dp(1, True, k)

    if result == INF:
        return "0\n"

    cuts = []
    path_tracking(u)

    return str(result) + "\n"


