        seen[u] = True
        if rem == 0 and sz[u] < k:
            target_dp[u] = depth
            path[u].extend(adj[u])
            return True

        if rem > sz[u] or seen[u]:
            return False

        for v, eid in adj[u]:
            if v == parent[u]:
                continue
            if sz[v] >= rem and not seen[v]:
                result = search(v, rem - sz[v], depth + 1)
                if result:
                    target_dp[u] = depth
                    path[u].append(eid)
                    return True

