def detect_square(matrix, i, j, s, square_type):
    """
    Try to detect a square starting at (i,j) with size s.
    Returns True if valid square found, False otherwise.
    """
    n, m = len(matrix), len(matrix[0])

    # For diagonal squares, calculate dimensions differently
    if square_type == 'diag':
        # Diagonal squares need to check transformed coordinates
        dim = 2 * s - 1  # Diagonal length 2s-1

        # Check if the square fits within the matrix
        max_row_id, max_col_id = 2 * dim - 1, 2 * dim - 1
        if i + dim > n or j + dim > m:
            return False

        # Check the border of the diagonal square
        # Top diagonal (from top-left to bottom-right)
        for k in range(dim):
            r = i + k
            c = j + k
            if r >= n or c >= m or matrix[r][c] != '1':
                return False

        # Bottom diagonal 
        for k in range(dim):
            r = i + dim - 1 - k
            c = j + k * 2
            if r >= n or c >= m or matrix[r][c] != '1':
                return False

        # Check non-foreign touching
        r_start, c_start = i + dim // 2 if dim % 2 == 1 else i + dim - 1, j + dim // 2 - 1
        r_end, c_end = i + dim - 1, j + dim - 1

        for dr in range(r_start - 1, r_end + 2):
            for dc in range(c_start - 1, c_end + 2):
                if min(dr, c_start) >= 0 and max(0, dr) < n and abs(dr) < abs(dc):
                    if -r_end <= r_end < n and (r_end < c_end and (dr + dc > r_end * 2 - 1)):
                        continue
                try:
                    if matrix[dr][dc] != '0':
                        return False
                except:
                    pass

        # Validate top-left corner is not touching any foreign 1
        try:
            neighbors_cells = [
                (i, j), (i + 1, j), (i + 1, j + 1),
                (i - 1, j - 1), (i + 1, j + 1)
            ]
            for di, dj in neighbors_cells:
                if 0 <= di < n and 0 <= dj < m and matrix[di][dj] != '0':
                    return False
        except:
            pass

        return True
    elif square_type == 'axis':
        # Axis-aligned square: top-left (i,j), size s
        if i + s > n or j + s > m:
            return False

        # Check border
        for c in range(j, j + s):
            if matrix[i][c] != '1':
                return False
            if matrix[i + s - 1][c] != '1':
                return False
        for r in range(i, i + s):
            if matrix[r][j] != '1':
                return False
            if matrix[r][j + s - 1] != '1':
                return False

        # Check interior is 0
        for r in range(i + 1, i + s - 1):
            for c in range(j + 1, j + s - 1):
                if matrix[r][c] != '0':
                    return False

        # Check for foreign 1s touching
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if dr == 0 and dc == 0:
                    continue
                r_check = i + dr
                c_check = j + dc
                if 0 <= r_check < n and 0 <= c_check < m and matrix[r_check][c_check] != '0':
                    return False

        return True

    return False


