            if parts[0] == '-1':
                left_child = int(parts[1])
                right_child = int(parts[2])
                tree[i] = {'l': left_child, 'r': right_child, 'is_leaf': False}
            else:
                tree[i] = {'val': int(parts[0]), 'is_leaf': True}

        # Compute using post-order traversal
        def compute(i):
            if tree[i]['is_leaf']:
                return {'leaf_count': 1, 'value': tree[i]['val']}

            l_result = compute(tree[i]['l'])
            r_result = compute(tree[i]['r'])

            l_count = l_result['leaf_count']
            r_count = r_result['leaf_count']

            # Total moves before reaching the merge at this node
            moves_before = (l_count - 1) + (r_count - 1)
            turn = moves_before  # 0-indexed turn number

            # Even turn: Pieguy maximizes, odd turn: Piegirl minimizes
            if turn % 2 == 0:
                result_value = max(l_result['value'], r_result['value'])
            else:
                result_value = min(l_result['value'], r_result['value'])

            return {'leaf_count': l_count + r_count, 'value': result_value}

        root_result = compute(0)
        results.append(str(root_result['value']))

    return '\n'.join(results)

