    def dfs_bridge(u, parent_edge):
        nonlocal timer
        timer[0] += 1
        tin[u] = low[u] = timer[0]
        bridge_count = [0]  # Use list to modify from nested function

        for v, edge_idx in adj[u]:
            if v == parent_edge:
                continue
            if tin[v]:
                low[u] = min(low[u], tin[v])
            else:
                bridge_count[0] += 1
                low[u] = min(low[u], low[v])
                if low[v] > tin[u]:
                    bridges.add(edge_idx)

    dfs_bridge(1, -1)

    # Check if all edges are bridges (graph must be 2-edge-connected)
    if len(bridges) > 0:
        return '0'

    # If no bridges, we can construct a strongly connected orientation
    # Using DFS tree approach to find back edges

    visited = [False] * (n + 1)
    result = [0] * m

    def dfs(u):
        visited[u] = True
        for v, edge_idx in adj[u]:
            if not visited[v]:
                result[edge_idx] = u
                dfs(v)

    # Start DFS from node 1
    dfs(1)

    # Build the graph to find long paths for cycles
    directed_graph = defaultdict(list)
    for i, (u, v) in enumerate(edges):
        if result[i] == u:
            directed_graph[u].append(v)
        else:
            directed_graph[v].append(u)

    # Check strong connectivity of the directed graph
    def is_strongly_connected(node, n, redirected_adj):
        visited = [False] * (n + 1)
        stack = [node]
        while stack:
            u = stack.pop()
            if visited[u]:
                continue
            visited[u] = True
            for v in redirected_adj[u]:
                if not visited[v]:
                    stack.append(v)

        if not all(visited):
            return False

        # Run DFS in reverse
        visited = [False] * (n + 1)
        stack = [node]
        while stack:
            u = stack.pop()
            if visited[u]:
                continue
            visited[u] = True
            for v in redirected_adj[u]:
                if not visited[v]:
                    stack.append(v)

        return all(visited)

    # Check if the current orientation works
    redirect_adj = defaultdict(list)
    for i, (u, v) in enumerate(edges):
        if result[i] == u:
            redirect_adj[u].append(v)
        else:
            redirect_adj[v].append(u)

    if not is_strongly_connected(1, n, redirect_adj):
        return '0'

    # Build output
    output = []
    for i, (u, v) in enumerate(edges):
        if result[i] == u:
            output.append(f"{u} {v}")
        else:
            output.append(f"{v} {u}")

    return '\n'.join(output)

