def compute_score(points):
    """Compute sum of squared distances between all pairs of points."""
    n = len(points)
    if n < 2:
        return 0
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            total += dx * dx + dy * dy
    return total

