import collections
from typing import List, Tuple

def bfs(start, adj, n):
    dist = [-1] * (n + 1)
    dist[start] = 0
    queue = collections.deque([start])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

