    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    dist_all = [[-1] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dist = bfs(i, adj, n)
        for j in range(1, n + 1):
            dist_all[i][j] = dist[j]

    # For efficiency, find top K incoming/outgoing for each node
    TOP_K = 5  # Use 5 candidates to avoid distinctness issues

    # top_in[v] = list of (distance, u) where u can reach v, sorted by distance descending
    top_in = [[] for _ in range(n + 1)]
    for v in range(1, n + 1):
        candidates = []
        for u in range(1, n + 1):
            if u != v and dist_all[u][v] != -1:
                candidates.append((dist_all[u][v], u))
        candidates.sort(reverse=True)
        top_in[v] = candidates[:TOP_K]

    # top_out[v] = list of (v->w distance, w), sorted by distance descending
    top_out = [[] for _ in range(n + 1)]
    for v in range(1, n + 1):
        candidates = []
        for w in range(1, n + 1):
            if w != v and dist_all[v][w] != -1:
                candidates.append((dist_all[v][w], w))
        candidates.sort(reverse=True)
        top_out[v] = candidates[:TOP_K]

    best_total = -1
    best_order = None

    # Try all pairs of (v2, v3) as middle cities
    for v2 in range(1, n + 1):
        for v3 in range(1, n + 1):
            if v2 == v3:
                continue
            mid_dist = dist_all[v2][v3]
            if mid_dist == -1:
                continue

            # Try all combinations from top_in[v2] and top_out[v3]
            for v1, d_in in top_in[v2]:
                for v4, d_out in top_out[v3]:
                    if v4 == v2 or v4 == v3:
