                    if v1 == v2 or v1 == v3:
                        continue

                    # All 4 must be distinct
                    if v1 == v4:
                        continue

                    total = d_in + mid_dist + d_out
                    if total > best_total:
                        best_total = total
                        best_order = [v1, v2, v3, v4]

    if best_order is None:
        return ""
    return " ".join(map(str, best_order))

