    for i in range(1, n):
        if i < len(lines):
            a, b = map(int, lines[i].split())
            adj[a].append(b)
            adj[b].append(a)

    # BFS to get topological order (parent pointers for tree rooting at 1)
    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    # dp[u] = {component_size: max_product_of_other_components}
    dp = [{} for _ in range(n + 1)]

    # Process in post-order (children before parent)
    for u in reversed(order):
        dp[u][1] = 1  # Base case: component of size 1, no other components

        for v in adj[u]:
            if v == parent[u]:
                continue

            child_dp = dp[v]
            u_dp = dp[u]

            # Create new dp state after processing this child
            new_dp = dict(u_dp)

            for s_u, prod_u in list(u_dp.items()):
                for s_v, prod_v in child_dp.items():
                    # Option 1: Keep edge (u,v) - merge components
                    # New component size is s_u + s_v
                    new_prod_keep = prod_u * prod_v * (s_u + s_v)
                    if s_u + s_v in new_dp:
                        new_dp[s_u + s_v] = max(new_dp[s_u + s_v], new_prod_keep)
                    else:
                        new_dp[s_u + s_v] = new_prod_keep

                    # Option 2: Cut edge (u,v) - v's component becomes separate
                    # v's component of size s_v contributes s_v to product
                    new_prod_cut = prod_u * prod_v * s_v
                    if s_u in new_dp:
                        new_dp[s_u] = max(new_dp[s_u], new_prod_cut)
                    else:
                        new_dp[s_u] = new_prod_cut

            dp[u] = new_dp

    # The answer is the maximum product across all possible component sizes at root
    if dp[1]:
        return str(max(dp[1].values()))
    else:
        return '1'

