    l = int(parts[2])
    r = int(parts[3])

    def power(a, b, m):
        result = 1
        a = a % m
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % m
            b = b >> 1
            a = (a * a) % m
        return result

    def inverse(a, m):
        return power(a, m - 2, m)

    def nCr(n, r, p):
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1
        num = 1
        den = 1
        for i in range(r):
            num = (num * (n - i)) % p
            den = (den * (i + 1)) % p
        return (num * inverse(den, p)) % p

    def count_valid_ab(a, b, p):
        """Count valid sequences of a A's and b B's where A_b never < B_b"""
        if b > a:
            return 0
        if a == 0 and b == 0:
            return 1
        # Ballot theorem: C(a+b, a) - C(a+b, a-1)
        total = nCr(a + b, a, p)
        invalid = nCr(a + b, a - 1, p)
        return (total - invalid + p) % p

    # Count all valid triples (a, b, c)
    ans = 0

    for a in range(n + 1):
        for b in range(n + 1 - a):
            c = n - a - b
            if c < 0:
                continue

            f = a - b
            if l <= f <= r:
                # Number of valid AB arrangements
                ab_valid = count_valid_ab(a, b, p)
                # Ways to place c C's in n positions among the AB+C sequence
                # Actually C's can be placed in the sequence freely
                # The number of ways is: (valid_AB_sequence) * C(n, c)
                # We choose c positions for C's, then place A's and B's in remaining
                # But we need to count sequences where A's and B's maintain validity
                # The formula is: valid_AB * C(a+b+c, c) / C(a+b, 0) = valid_AB * C(n, c)
                ways_to_place_c = nCr(n, c, p)
                ans = (ans + ab_valid * ways_to_place_c) % p

    return str(ans)


