    lines = input_str.strip().split('\n')

    # Parse vowel/consonant string
    vcs = lines[0]
    n, m = map(int, lines[1].split())

    # Parse rules
    rules = []
    for i in range(m):
        parts = lines[2 + i].split()
        pos1 = int(parts[0]) - 1  # 0-indexed
        t1 = parts[1]
        pos2 = int(parts[2]) - 1
        t2 = parts[3]
        rules.append((pos1, t1, pos2, t2))

    s = list(lines[2 + m])

    def get_type(char):
        """Return 'V' or 'C' based on vowel_consonant string"""
        return vcs[ord(char) - ord('a')]

    def is_valid(word):
        """Check if word satisfies all rules"""
        for pos1, t1, pos2, t2 in rules:
            if get_type(word[pos1]) == t1:
                if get_type(word[pos2]) != t2:
                    return False
        return True

    l = len(vcs)
    alphabet = [chr(ord('a') + i) for i in range(l)]
    result = None
    word = [''] * n

    def backtrack(pos, exceeded):
        """
        Try to build a valid word >= s
        exceeded: True if we've already chosen a character > s[pos] at some position
        """
        nonlocal result

        if result is not None:
            return True

        if pos == n:
            if is_valid(word):
                result = ''.join(word)
                return True
            return False

        # Determine which characters to try
        if exceeded:
            start_idx = 0
        else:
            start_idx = ord(s[pos]) - ord('a')

        # Try each character in lexicographic order
        for i in range(start_idx, l):
            word[pos] = alphabet[i]
            exceeded_this_pos = exceeded or (i > ord(s[pos]) - ord('a'))

            # Check if this character could lead to a valid completion
            # We can do a quick check with already-placed characters
            can_proceed = True
            for rule_pos1, t1, rule_pos2, t2 in rules:
                if rule_pos1 < pos:
                    if get_type(word[rule_pos1]) == t1:
                        if rule_pos2 == pos:
                            if get_type(word[pos]) != t2:
                                can_proceed = False
                                break

            if can_proceed:
                if backtrack(pos + 1, exceeded_this_pos):
                    return True

        return False

    # First check if s itself is valid
    if is_valid(list(s)):
        result = ''.join(s)
    else:
        result = None
        backtrack(0, False)

    return result if result else "-1"

