            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

def get_euler_phi(n):
    """Compute Euler's totient function."""
    if n == 1:
        return 1
    result = n
    p = 2
    temp = n
    while p * p <= temp:
        if temp % p == 0:
            while temp % p == 0:
                temp //= p
            result -= result // p
        p += 1
    if temp > 1:
        result -= result // temp
    return result

