import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, d = map(int, lines[0].split())

    circles = []
    for line in lines[1:]:
        parts = line.split()
        x, y, r = int(parts[0]), int(parts[1]), int(parts[2])
        circles.append((x, y, r))

    if n == 0:
        return "0"

    # Normalized angle to [0, 2π)
    def normalize_angle(angle):
        angle = angle % (2 * math.pi)
        if angle < 0:
            angle += 2 * math.pi
        return angle

    # Number of angular bins (higher = better resolution)
    ANGLE_STEPS = 32768
    ANGLE_RANGE = 2 * math.pi
    bin_size = ANGLE_RANGE / ANGLE_STEPS

    # Maximum meaningful distance (farthest point from origin among all circles)
    max_distance = 0
    for i, (cx, cy, r) in enumerate(circles):
        dist = math.hypot(cx, cy)
        max_distance = max(max_distance, dist + r)

    num_distance_bins = int(math.ceil(max_distance / d)) + 2

    # count[dist_idx][angle_bin] = number of circles that hit at this distance/direction
    count = [[0] * ANGLE_STEPS for _ in range(num_distance_bins)]

    for i, (cx, cy, r) in enumerate(circles):
        dist_center = math.hypot(cx, cy)

        if dist_center < r:
            # Origin is inside this circle - can hit at any distance with any direction
            for dist_idx in range(1, num_distance_bins):
                actual_dist = dist_idx * d
                if actual_dist < r:
                    continue
                # Full angle range
                for bin_idx in range(ANGLE_STEPS):
                    count[dist_idx][bin_idx] += 1
            continue

        # Angular interval from the circle
        angle_center = math.atan2(cy, cx)
        if angle_center < 0:
            angle_center += 2 * math.pi

        # Half angular width (from center ray to tangent)
        if dist_center > r:
            half_angle = math.asin(r / dist_center)
            half_angle_global = 2 * half_angle  # Total angular width
        else:
            # Origin on or inside circle - handled above
            continue

        start_angle = angle_center - half_angle
        end_angle = angle_center + half_angle

        # Normalize to [0, 2π)
        start_angle = normalize_angle(start_angle)
        end_angle = normalize_angle(end_angle)

        # Determine valid distance range for this circle
        min_dist = dist_center - r
        max_dist = dist_center + r

        start_dist = 1
        if min_dist > 0:
            start_dist = int(math.ceil(min_dist / d))

        end_dist = int(math.ceil(max_dist / d))
        if end_dist > num_distance_bins - 1:
            end_dist = num_distance_bins - 1

        for dist_idx in range(start_dist, end_dist + 1):
            actual_dist = dist_idx * d
            if actual_dist < min_dist:
                continue
            if actual_dist > max_dist:
                continue

            # Increment this distance bin for the angular interval
            start_bin = start_angle // bin_size
            end_bin = end_angle // bin_size

            if start_bin <= end_bin:
                for bin_idx in range(start_bin, end_bin + 1):
                    if bin_idx < ANGLE_STEPS:
                        count[dist_idx][bin_idx] += 1
            else:
                # Wraps around 2π
                for bin_idx in range(start_bin):
                    if bin_idx < ANGLE_STEPS:
                        count[dist_idx][bin_idx] += 1
                for bin_idx in range(end_bin + 1, ANGLE_STEPS):
                    count[dist_idx][bin_idx] += 1

    # Find maximum count across all bins
    max_points = 0
    for dist_idx in range(len(count)):
        for bin_idx in range(ANGLE_STEPS):
            if count[dist_idx][bin_idx] > max_points:
                max_points = count[dist_idx][bin_idx]

    return str(max_points)


