memo = {}

def can_first_win(a, e):
    if a > e:
        return False

    key = (a, e)
    if key in memo:
        return memo[key]

    # Both moves are loss for first player
    if 2*a > e and a+1 > e:
        result = False
    elif 2*a > e:
        # Must choose a+1
        result = not can_first_win(a+1, e)
    elif a+1 > e:
        # Must choose 2*a
        result = not can_first_win(2*a, e)
    else:
        # Can choose either
        result = (not can_first_win(a+1, e)) or (not can_first_win(2*a, e))

    memo[key] = result
    return result

