    heights = list(map(int, lines[1].split()))

    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            # Check clockwise path from i to j
            clockwise = True
            if j == i + 1:
                # Adjacent - can see each other
                count += 1
                continue

            # Check clockwise path through (i+1), (i+2), ..., (j-1)
            k = (i + 1) % n
            while k != j:
                if heights[k] > max(heights[i], heights[j]):
                    clockwise = False
                    break
                k = (k + 1) % n

            if clockwise:
                count += 1
                continue

            # Check counter-clockwise path if clockwise was blocked
            # Path through (i-1), (i-2), ..., (j+1)
            counter = True
            k = (i - 1) % n
            if k == j:
                # Adjacent counter-clockwise
                counter = False
            else:
                while k != j:
                    if heights[k] > max(heights[i], heights[j]):
                        counter = False
                        break
                    k = (k - 1) % n

            if counter:
                count += 1

    return f"{count}\n"

MOD = 998244353

def power(a, b, m):
    res = 1
    a %= m
    while b > 0:
        if b % 2 == 1:
            res = res * a % m
        a = a * a % m
        b //= 2
    return res

def inverse(n, m=MOD):
    return power(n, m - 2, m)

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    num = 1
    for i in range(r):
        num = num * (n - i) % MOD
    den = 1
    for i in range(1, r + 1):
        den = den * i % MOD
    return num * inverse(den) % MOD

def binomial_tail(n, k, p):
    """Calculate P(Binomial(n, p) ≥ k) mod MOD"""
    if k <= 0:
        return 1 % MOD
    if k > n:
        return 0
    result = 0
    for i in range(k, n + 1):
        # C(n,i) * p^i * (1-p)^(n-i)
        term = nCr(n, i)
        term = term * power(p, i, MOD) % MOD
        inv_p = inverse(power(2 * MOD - 2, MOD - 2, MOD) % MOD)
        inv_p = power(1 - p, n - i, MOD)
        term = term * inv_p % MOD
        result = (result + term) % MOD
    return result

